SELECT /*selectMasterMpRqQuotationReturnMsds*/ X.BTOA_DATE, X.DESCRIPTION, X.UNIT_MEASURE, X.MAKER_NAME, X.AGENT, X.BTOA_USER_NAME, X.KEP_USER_ID, X.SOURCING_STATUS, X.BUYER_ITEM_NO, X.BTOA_END_DATE, X.SPECIFICATION, X.ITEM_QTY, X.ORIGIN_NAME, X.BUYER_TARGET_PRICE, X.ATOB_UNIT_PRICE, X.BTOA_USER_DEPT, X.ATOB_REMARK, X.IMAGE_KEY, X.BUYER, X.QUOTATION_NO, X.QUOTATION_SEQ, X.REVISION, X.KEP_USER_NAME, X.AGENT_NAME, X.REG_ITEM_NO, X.CONTRACT_NO, X.CONTRACT_SEQ, X.BYCA_COMORG_CODE, X.BUYER_NAME, X.BTOA_END_TIME, X.BTOA_REMARK, X.AGENT_OPEN_FLAG, X.STOA_LIST_PRICE, X.ORIGIN_CODE, X.LEAD_TIME, X.LOAD_USER_ID, X.ATOB_DATE, NVL(TRIM(X.CMS_CATEG_ID), 'NO_CATEG') AS CMS_CATEG_ID, NVL(TRIM(X.CMS_CATLG_ID), 'NO_CATLG') AS CMS_CATLG_ID, X.PROCESS_TYPE, X.IMPORT_FLAG, X.WAREHOUSE_CODE, X.BELOW_COMORG_CODE, X.ITEM_GROUP , X.ITEM_DETAIL_DESC , X.IMGFILE_NAME , X.ITEM_TYPE , X.ITEM_TYPE_TEXT , X.GREEN_FLAG , X.ITEM_GUBUN , X.REG_ITEM_NO2 , DECODE(X.RE_ITEM_NO,NULL,'',SUBSTR(X.RE_ITEM_NO,12,6)) AS RE_ITEM_NO , X.MSDS_YN , X.MSDS_STATUS , X.MSDS_NO , X.MSDS_TYPE_TEXT , X.MSDS_NOTE , '1' AS PRINT ,DECODE(X.CANCEL_REMARK,'',2,3) AS CANCEL_REMARK_IMG , X.CANCEL_REMARK FROM( SELECT MAX(A.BTOA_DATE) AS BTOA_DATE, MAX(A.DESCRIPTION) AS DESCRIPTION, MAX(A.UNIT_MEASURE) AS UNIT_MEASURE, MAX(A.MAKER_NAME) AS MAKER_NAME, MAX(B.AGENT) AS AGENT, MAX(A.BTOA_USER_NAME) AS BTOA_USER_NAME, MAX(A.KEP_USER_ID) AS KEP_USER_ID, MAX(DECODE(A.RECV_FLAG,'GR','결재반려',DECODE(NVL(A.BTOA_NEGO_PRICE,0),0,'합의대상','Nego합의대상'))) AS SOURCING_STATUS, MAX(A.BUYER_ITEM_NO) AS BUYER_ITEM_NO, MAX(A.BTOA_END_DATE) AS BTOA_END_DATE, MAX(SUBSTR(NVL(A.BTOA_END_TIME,'19'),0,2))||':'||MAX(SUBSTR(NVL(A.BTOA_END_TIME,'00'),3,2)) AS BTOA_END_TIME, MAX(A.SPECIFICATION) AS SPECIFICATION, MAX(NVL(A.ITEM_QTY,0)) AS ITEM_QTY, MAX((SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'M001' AND CODE = A.ORIGIN_CODE)) AS ORIGIN_NAME, MAX(NVL(A.BUYER_TARGET_PRICE,0)) AS BUYER_TARGET_PRICE, MAX(NVL(A.ATOB_UNIT_PRICE,0)) AS ATOB_UNIT_PRICE, MAX((SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE = A.BUYER AND TYPE = 'C001' AND CODE = A.BTOA_USER_DEPT)) AS BTOA_USER_DEPT, MAX(TRIM(A.ATOB_REMARK)) AS ATOB_REMARK, MAX(TRIM(A.IMAGE_KEY)) AS IMAGE_KEY, A.BUYER, A.QUOTATION_NO, A.QUOTATION_SEQ, A.REVISION, MAX((SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = A.KEP_USER_ID)) AS KEP_USER_NAME, MAX((SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE=B.AGENT)) AS AGENT_NAME, MAX(A.REG_ITEM_NO) AS REG_ITEM_NO, MAX(A.CONTRACT_NO) AS CONTRACT_NO, MAX(A.CONTRACT_SEQ) AS CONTRACT_SEQ, MAX((SELECT BYCA_COMORG_CODE FROM ICOMCMPY WHERE COM_CODE = A.BUYER AND STATUS IN ('C','R'))) AS BYCA_COMORG_CODE, MAX((SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = A.BUYER)) AS BUYER_NAME, MAX(NVL(TRIM(A.BTOA_REMARK),'')) AS BTOA_REMARK, MAX(A.AGENT_OPEN_FLAG) AS AGENT_OPEN_FLAG, MAX(B.STOA_LIST_PRICE) AS STOA_LIST_PRICE, MAX(A.ORIGIN_CODE) AS ORIGIN_CODE, MAX(B.LEAD_TIME) AS LEAD_TIME, MAX(A.LOAD_USER_ID) AS LOAD_USER_ID, MAX(A.ATOB_DATE) AS ATOB_DATE, MAX(A.CMS_CATEG_ID) AS CMS_CATEG_ID, MAX(A.CMS_CATLG_ID) AS CMS_CATLG_ID, MAX(A.PROCESS_TYPE) AS PROCESS_TYPE, MAX(A.IMPORT_FLAG) AS IMPORT_FLAG, MAX(NVL(A.WAREHOUSE_CODE,'')) AS WAREHOUSE_CODE, MAX(A.BELOW_COMORG_CODE) AS BELOW_COMORG_CODE, MAX(A.ITEM_GROUP) AS ITEM_GROUP , MAX(A.ITEM_DETAIL_DESC) AS ITEM_DETAIL_DESC , MAX(A.IMGFILE_NAME) AS IMGFILE_NAME , MAX(DECODE(A.ITEM_TYPE,'T','계약요청품목','O','일회성품목','N','미분류')) AS ITEM_TYPE_TEXT , MAX(A.ITEM_TYPE) AS ITEM_TYPE , MAX(NVL(A.GREEN_FLAG,'N')) AS GREEN_FLAG , MAX(A.ITEM_GUBUN) AS ITEM_GUBUN , MAX(SUBSTR(A.REG_ITEM_NO,0,10)) AS REG_ITEM_NO2 ,MAX((SELECT ITEM_NO FROM ICOMCQDT CQDT WHERE CQDT.BUYER = A.BUYER AND CQDT.BUYER_ITEM_NO = A.BUYER_ITEM_NO AND CQDT.CONTRACT_NO = A.CONTRACT_NO AND CQDT.CONTRACT_SEQ = A.CONTRACT_SEQ AND CQDT.STATUS IN ('C','R') ) ) RE_ITEM_NO , MAX(NVL(A.MSDS_YN,'N')) AS MSDS_YN , MAX(A.MSDS_STATUS) AS MSDS_STATUS , MAX(A.MSDS_NO) AS MSDS_NO , MAX(A.MSDS_NOTE) AS MSDS_NOTE , MAX(DECODE(NVL(A.MSDS_YN,'N')||A.MSDS_STATUS,'YC','MSDS 미승인','YA','MSDS 승인')) AS MSDS_TYPE_TEXT , MAX(A.CANCEL_REMARK) AS CANCEL_REMARK FROM KEPRQDT A, KEPQTDT B WHERE 1=1 AND A.SO_CA_FLAG='SO' AND A.BUYER=B.BUYER AND A.QUOTATION_NO=B.QUOTATION_NO AND A.QUOTATION_SEQ=B.QUOTATION_SEQ AND A.REVISION=B.REVISION AND B.BID_SUCCESS_FLAG = 'Y' AND A.ATOB_UNIT_PRICE <> 0 AND A.CONFIRM_DATE IS NULL AND A.RECV_FLAG IN ('GA','GR') AND A.ATOB_SEND_FLAG = 'Y' AND A.STATUS IN ('C','R') AND B.STATUS <> 'D' AND B.STATUS <> 'O' AND A.MSDS_STATUS = 'R'
AND A.BTOA_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND B.ATOS_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND A.BTOA_END_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND B.BUYER IN
#{item}
AND B.ATOS_END_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND A.QUOTATION_NO = #{st_quotation_no}
AND A.BUYER IN
#{item}
AND A.KEP_USER_ID = #{st_kep_user_id}
AND A.MAKER_CODE = #{st_maker_code}
AND A.BTOA_USER_NAME LIKE '%' || #{st_btoa_user_name} || '%'
AND (A.DESCRIPTION LIKE '%' || #{st_desc_spec} || '%' OR A.SPECIFICATION LIKE '%' || #{st_desc_spec} || '%')
AND A.BUYER_ITEM_NO LIKE '%' || #{st_buyer_item_no} || '%'
AND A.BTOA_USER_NAME = #{st_btoa_user_name}
AND (A.DESCRIPTION = #{st_desc_spec} OR A.SPECIFICATION = #{st_desc_spec})
AND A.BUYER_ITEM_NO = #{st_buyer_item_no}
GROUP BY A.BUYER, A.QUOTATION_NO, A.QUOTATION_SEQ, A.REVISION ORDER BY A.BUYER, A.QUOTATION_NO, A.QUOTATION_SEQ, A.REVISION ) X
ORDER BY X.ATOB_DATE DESC


