/*updateQuotationProceState2*/
	UPDATE	KEPRQDT A
	SET		A.MSDS_YN = 'Y',
			A.MSDS_NO = '',
			A.MSDS_USER_ID = '',
			A.MSDS_STATUS = 'N'
	WHERE	A.BUYER = #{BUYER}
	AND		A.QUOTATION_NO = #{QUOTATION_NO}
	AND		A.QUOTATION_SEQ = #{QUOTATION_SEQ}
	AND		A.REVISION = #{REVISION}
	AND		A.STATUS <> 'D'


/*saveMasterMpRqQuotationAtoSDate*/
	UPDATE KEPQTDT A 
		SET                                    
		    A.ATOS_END_DATE = #{TO_ATOS_END_DATE}
		    , A.ATOS_END_TIME = #{TO_ATOS_END_TIME}   
		    , A.ADMIN_RENEWAL_FLAG = 'Y'
		 WHERE A.BUYER = #{BUYER}                                    
		   AND A.QUOTATION_NO = #{QUOTATION_NO}                                   
		   AND A.QUOTATION_SEQ = #{QUOTATION_SEQ}                                    
		   AND A.REVISION = #{REVISION}
		   AND A.AGENT_REVISION = #{AGENT_REVISION}                                     
		   AND A.STATUS <> 'D'

