/*selectMasterMpRqQtdtAgentList*/
	SELECT
	 QTDT.AGENT AS AGENT
	 ,QTDT.DSS_CHOICE AS DSS_CHOICE
	 ,QTDT.DSS_FLAG AS DSS_FLAG
	 ,TO_CHAR(QTDT.STOA_LIST_PRICE) AS STOA_LIST_PRICE
	 ,TO_CHAR(QTDT.LEAD_TIME) AS LEAD_TIME
	 ,QTDT.SEL_USER_ID AS SEL_USER_ID
	 ,QTDT.SEL_USER_NAME AS SEL_USER_NAME
	 ,TO_CHAR(QTDT.SEL_USER_TEL) AS SEL_USER_TEL
	FROM KEPQTDT QTDT
	WHERE QTDT.BUYER = #{BUYER}
	AND QTDT.QUOTATION_NO = #{QUOTATION_NO}
	AND QTDT.QUOTATION_SEQ = #{QUOTATION_SEQ}
	AND QTDT.REVISION=#{REVISION}
	AND QTDT.STATUS IN ('C','R')


SELECT/*selectMasterMpRqQuotationRevision*/							
		NVL(MAX(AGENT_REVISION)+1,0) AS AGENT_REVISION
  FROM KEPQTDT					
 WHERE BUYER=#{BUYER} 					
	AND QUOTATION_NO=#{QUOTATION_NO}		
	AND QUOTATION_SEQ=#{QUOTATION_SEQ}				
	AND REVISION=#{REVISION}     			
	AND STATUS IN ('C','R','O')

