	UPDATE KEPQTDT	/*updateMasterMpRqPreQtdt*/				
	   SET STATUS='O'  
    WHERE BUYER=#{BUYER}   
      AND QUOTATION_NO=#{QUOTATION_NO}   
      AND QUOTATION_SEQ=#{QUOTATION_SEQ}     
      AND REVISION=#{REVISION}       
      AND STATUS IN ('C','R')


	UPDATE KEPRQDT   /*updateMasterMpRqRqdt*/             
      SET ATOB_SEND_FLAG='N',
      	  ATOS_REMARK = #{ATOS_REMARK},
      	  ATOS_REMARK2 = ATOS_REMARK2||#{AGENT_REVISION}||'차: '||#{ATOS_REMARK}||',',
          KEP_USER_ID=#{st_user_id},
          MSDS_NO = '',
          MSDS_USER_ID = '',
          MSDS_STATUS = 'N'
    WHERE BUYER=#{BUYER}     
      AND QUOTATION_NO=#{QUOTATION_NO} 
      AND QUOTATION_SEQ=#{QUOTATION_SEQ} 
      AND REVISION=#{REVISION}
      AND STATUS <> 'D'

