/*selectAgentImagekey*/
	SELECT	NVL(SELLER_IMAGE_KEY, 'X') AS SELLER_IMAGE_KEY
	FROM	KEPQTDT
	WHERE	1=1
	AND		BUYER = #{BUYER}
	AND		QUOTATION_NO = #{QUOTATION_NO}
	AND		QUOTATION_SEQ = #{QUOTATION_SEQ}
	AND		REVISION = #{REVISION}
	AND		BID_SUCCESS_FLAG = 'Y'
	AND		STATUS = 'C'

