UPDATE KEPRQDT /*updateMasterMpRqAnyItmCheSend*/
   SET ITEM_MD_USER_ID = #{st_user_id}
   ,ITEM_MD_DATE = SYSDATE
   ,ITEM_CHG_REQ_IMAGE_KEY = NULL
   ,DELETE_SCHD_DATE = NULL
 WHERE BUYER = #{BUYER}
   AND QUOTATION_NO = #{QUOTATION_NO}    
   AND QUOTATION_SEQ = #{QUOTATION_SEQ}    
   AND REVISION = #{REVISION}
   AND STATUS <> 'D'


UPDATE KEPRQDT /*updateMasterMpRqAnyAfterItmCheSend*/
   SET AFTER_ITEM_MD_USER_ID = #{st_user_id}
   ,AFTER_ITEM_MD_DATE = SYSDATE
   ,AFTER_ITEM_CHG_REQ_IMAGE_KEY = NULL
   ,DELETE_SCHD_DATE = NULL
 WHERE BUYER = #{BUYER}
   AND QUOTATION_NO = #{QUOTATION_NO}    
   AND QUOTATION_SEQ = #{QUOTATION_SEQ}    
   AND REVISION = #{REVISION}
   AND STATUS <> 'D'


UPDATE KEPRQDT /*updateMasterMpRqAnyNegoItmCheSend*/
   SET DELETE_SCHD_DATE = NULL
 WHERE BUYER = #{BUYER}
   AND QUOTATION_NO = #{QUOTATION_NO}    
   AND QUOTATION_SEQ = #{QUOTATION_SEQ}    
   AND REVISION = #{REVISION}
   AND STATUS <> 'D'


UPDATE KEP_ITEM_MD_REQ /*updateMasterMpRqAnyItmMdSend*/
   SET ITEM_MD_USER_ID = #{st_user_id}
   ,ITEM_MD_DATE = SYSDATE
 WHERE BUYER = #{BUYER}
   AND QUOTATION_NO = #{QUOTATION_NO}    
   AND QUOTATION_SEQ = #{QUOTATION_SEQ}    
   AND REVISION = #{REVISION}
   AND ITEM_MD_REVISION = #{ANY_ITEM_MD_REQ_REVISION}
   AND ITEM_MD_STATUS = 'C'


UPDATE KEP_AFTER_ITEM_MD_REQ /*updateMasterMpRqAnyAfterItmMdSend*/
   SET ITEM_MD_USER_ID = #{st_user_id}
   ,ITEM_MD_DATE = SYSDATE
 WHERE BUYER = #{BUYER}
   AND QUOTATION_NO = #{QUOTATION_NO}    
   AND QUOTATION_SEQ = #{QUOTATION_SEQ}    
   AND REVISION = #{REVISION}
   AND ITEM_MD_REVISION = #{ANY_ITEM_MD_REQ_REVISION}
   AND ITEM_MD_STATUS = 'C'


UPDATE KEP_NEGO_ITEM_MD_REQ /*updateMasterMpRqAnyNegoItmMdSend*/
   SET ITEM_MD_USER_ID = #{st_user_id}
   ,ITEM_MD_DATE = SYSDATE
 WHERE BUYER = #{BUYER}
