UPDATE KEPRQDT /*saveRemarkPop*/
   SET  ATOB_REMARK = #{re_atob_remark}
   ,	BTOA_REMARK = #{re_btoa_remark}				 
   , 	ATOA_REMARK = #{re_atoa_remark}				   
WHERE	1=1
